{"command":"cd "$HOME/gcmbuild" && cat > gcmbench.c << 'EOF'
#include <nettle/gcm.h>
#include <nettle/aes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

int main() {
    size_t n = 60000UL * 1024;
    uint8_t *pt = malloc(n);
    uint8_t *ct = malloc(n);
    memset(pt, 0x5a, n);
    uint8_t key[16], nonce[12], aad[32], tag[16];
    memset(key, 1, 16); memset(nonce, 2, 12); memset(aad, 3, 32);

    struct gcm_aes128_ctx ctx;
    // warmup
    gcm_aes128_set_key(&ctx, key);
    gcm_aes128_set_iv(&ctx, 12, nonce);
    gcm_aes128_update(&ctx, 32, aad);
    gcm_aes128_encrypt(&ctx, n, ct, pt);
    gcm_aes128_digest(&ctx, 16, tag);

    int reps = 5;
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        gcm_aes128_set_key(&ctx, key);
        gcm_aes128_set_iv(&ctx, 12, nonce);
        gcm_aes128_update(&ctx, 32, aad);
        gcm_aes128_encrypt(&ctx, n, ct, pt);
        gcm_aes128_digest(&ctx, 16, tag);
    }
    double t1 = now();
    printf("nettle aes128 gcm: %.2f ms\n", (t1-t0)/reps*1000);
    printf("tag: ");
    for (int i = 0; i < 16; i++) printf("%02x", tag[i]);
    printf("\nct[:16]: ");
    for (int i = 0; i < 16; i++) printf("%02x", ct[i]);
    printf("\n");

    // throughput of encrypt only
    gcm_aes128_set_key(&ctx, key);
    gcm_aes128_set_iv(&ctx, 12, nonce);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        gcm_aes128_encrypt(&ctx, n, ct, pt);
    }
    t1 = now();
    printf("encrypt only (no rekey): %.2f ms\n", (t1-t0)/reps*1000);
    return 0;
}
EOF
cc -O2 -I/usr/local/include -L/usr/local/lib -o gcmbench gcmbench.c -lnettle && ./gcmbench"}

{"command":"cd "$HOME/gcmbuild" && cat > osslbench.c << 'EOF'
#include <openssl/evp.h>
#include <openssl/provider.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static void run(const char *label, EVP_CIPHER *cipher, const uint8_t *key, const uint8_t *nonce,
                const uint8_t *pt, size_t n, const uint8_t *aad, int reps) {
    uint8_t *ct = malloc(n);
    uint8_t tag[16];
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    // warmup
    for (int w = 0; w < 1; w++) {
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        int outl = 0;
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct, &outl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        int outl = 0;
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, (int)n);
        EVP_EncryptFinal_ex(ctx, ct, &outl);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("%s: %.2f ms  ct[:4]=%02x%02x%02x%02x tag[:4]=%02x%02x%02x%02x\n",
           label, (t1-t0)/reps*1000, ct[0],ct[1],ct[2],ct[3], tag[0],tag[1],tag[2],tag[3]);
    EVP_CIPHER_CTX_free(ctx);
    free(ct);
}

int main() {
    size_t n = 60000UL * 1024;
    uint8_t *pt = malloc(n);
    memset(pt, 0x5a, n);
    uint8_t key[16], nonce[12], aad[32];
    memset(key, 1, 16); memset(nonce, 2, 12); memset(aad, 3, 32);

    // default
    run("default EVP_aes_128_gcm", (EVP_CIPHER*)EVP_aes_128_gcm(), key, nonce, pt, n, aad, 3);

    // fetch from default provider explicitly
    EVP_CIPHER *c = EVP_CIPHER_fetch(NULL, "AES-128-GCM", "provider=default");
    printf("fetch default: %p\n", (void*)c);
    if (c) run("fetch provider=default", c, key, nonce, pt, n, aad, 3);

    // Try legacy provider
    OSSL_PROVIDER_load(NULL, "legacy");
    EVP_CIPHER *c2 = EVP_CIPHER_fetch(NULL, "AES-128-GCM", NULL);
    printf("fetch any: %p name=%s\n", (void*)c2, EVP_CIPHER_get0_name(c2));
    if (c2) run("fetch any", c2, key, nonce, pt, n, aad, 3);

    // list providers
    printf("default available: %d\n", OSSL_PROVIDER_available(NULL, "default"));
    printf("legacy available: %d\n", OSSL_PROVIDER_available(NULL, "legacy"));
    return 0;
}
EOF
