    void (*stream)(const unsigned char*, unsigned char*, size_t, const void*, const unsigned char*));
void CRYPTO_gcm128_tag(void *ctx, unsigned char *tag, size_t len);
void *CRYPTO_gcm128_init(void *ctx, void *key, void (*block)(const unsigned char*, unsigned char*, const void*));

int AES_set_encrypt_key(const unsigned char *userKey, const int bits, void *key);
void AES_encrypt(const unsigned char *in, unsigned char *out, const void *key);

