    aesni_encrypt(in, out1, aeskey);
    AES_set_encrypt_key(key, 128, aeskey);
    AES_encrypt(in, out2, aeskey);
    printf("aesni block: "); for (int i=0;i<16;i++) printf("%02x", out1[i]); printf("\n");
    printf("AES   block: "); for (int i=0;i<16;i++) printf("%02x", out2[i]); printf("\n");

    /* Re-set with aesni after AES_set overwrote */
    aesni_set_encrypt_key(key, 128, aeskey);

    /* Benchmark aesni_ctr32 */
    unsigned char ivec[16]; memset(ivec, 2, 16);
    int reps = 3;
