        aesni_ctr32_encrypt_blocks(pt, ct, n/16, aeskey, iv2);
    }
    double t1 = now();
    printf("aesni_ctr32: %.2f ms (%.0f MB/s)\n", (t1-t0)/reps*1000, (n/1e6) / ((t1-t0)/reps));

    /* Benchmark ghash avx */
    u128 H; memset(&H, 0, sizeof(H));
    aesni_encrypt((unsigned char*)&H, (unsigned char*)&H, aeskey); /* not quite right but fine for bench */
    u128 Htable[16];
    gcm_init_avx(Htable, &H);
    u128 Xi; memset(&Xi, 0, sizeof(Xi));
    t0 = now();
    for (int i = 0; i < reps; i++) {
        u128 Xi2; memset(&Xi2, 0, sizeof(Xi2));
        gcm_ghash_avx(&Xi2, Htable, pt, n);
    }
    t1 = now();
    printf("ghash_avx: %.2f ms (%.0f MB/s)\n", (t1-t0)/reps*1000, (n/1e6) / ((t1-t0)/reps));

    gcm_init_clmul(Htable, &H);
    t0 = now();
    for (int i = 0; i < reps; i++) {
        u128 Xi2; memset(&Xi2, 0, sizeof(Xi2));
        gcm_ghash_clmul(&Xi2, Htable, pt, n);
    }
    t1 = now();
    printf("ghash_clmul: %.2f ms (%.0f MB/s)\n", (t1-t0)/reps*1000, (n/1e6) / ((t1-t0)/reps));

