/* We'll intercept by using a custom ENGINE? Can't easily. Instead, use the fact that
   EVP_CIPHER_CTX has a known layout in OpenSSL 3.x. Let's print the struct offsets by
   including internal headers if present, else brute force: after EncryptInit, scan memory. */

int main() {
    /* Print sizeof and dump EVP_CIPHER_CTX via public accessors */
    unsigned char key[16]; memset(key, 1, 16);
    unsigned char nonce[12]; memset(nonce, 2, 12);
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);

    printf("ctx ptr %p\n", (void*)ctx);
    printf("EVP_CIPHER_CTX_get_cipher_data? ");
    /* Not public. Let's just dump the first 256 bytes of pointers inside ctx. */
    void **p = (void**)ctx;
    for (int i = 0; i < 40; i++) {
        printf("  [%2d] %p\n", i, p[i]);
    }
    printf("sizeof guess: block size %d keylen %d ivlen %d\n",
        EVP_CIPHER_CTX_get_block_size(ctx),
        EVP_CIPHER_CTX_get_key_length(ctx),
        EVP_CIPHER_CTX_get_iv_length(ctx));

    /* cipher_data is typically at a fixed offset. In OpenSSL 3.x EVP_CIPHER_CTX:
       We'll search for the AES key schedule by computing expected first round key. */
    unsigned char ks[256];
    memset(ks, 0, sizeof(ks));
    int aesni_set_encrypt_key(const unsigned char*, int, void*);
    aesni_set_encrypt_key(key, 128, ks);
    printf("expected ks[0..15]: ");
    for (int i = 0; i < 16; i++) printf("%02x", ks[i]);
    printf("\n");

    unsigned char *base = (unsigned char*)ctx;
    int found = 0;
    for (int off = 0; off < 4096 && !found; off++) {
        if (memcmp(base + off, ks, 16) == 0) {
            printf("found key schedule at ctx+%d\n", off);
            found = 1;
        }
    }
    /* also search heap pointers */
    for (int i = 0; i < 40; i++) {
        unsigned char *q = (unsigned char*)p[i];
        if ((uintptr_t)q < 0x1000) continue;
        for (int off = 0; off < 2048; off++) {
            if (memcmp(q + off, ks, 16) == 0) {
                printf("found ks via ptr[%d]+%d (ptr=%p)\n", i, off, (void*)q);
                goto done;
            }
        }
    }
done:
    return 0;
}
EOF
