#include <openssl/evp.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct { uint64_t hi, lo; } u128;
void gcm_init_avx(u128 Htable[16], const u128 *H);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, void *key);
void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                         const void *key, unsigned char ivec[16], u128 *Xi);
void gcm_ghash_avx(u128 *Xi, const u128 Htable[16], const unsigned char *inp, size_t len);

static void bswap16(unsigned char *p) {
    for (int i = 0; i < 8; i++) { unsigned char t = p[i]; p[i] = p[15-i]; p[15-i] = t; }
}

static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

int main() {
    unsigned char keyb[16]; memset(keyb, 1, 16);
    unsigned char nonce[12]; memset(nonce, 2, 12);
    unsigned char aad[32]; memset(aad, 3, 32);
    size_t n = 60000UL * 1024;
    unsigned char *pt = malloc(n); memset(pt, 0x5a, n);
    unsigned char *ct = malloc(n);

    /* reference via EVP */
    EVP_CIPHER_CTX *ectx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ectx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ectx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ectx, NULL, NULL, keyb, nonce);
    int outl = 0;
    EVP_EncryptUpdate(ectx, NULL, &outl, aad, 32);
    unsigned char *ref = malloc(n);
    EVP_EncryptUpdate(ectx, ref, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(ectx, ref, &outl);
    unsigned char tag[16];
    EVP_CIPHER_CTX_ctrl(ectx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    printf("ref ct[:16]: "); for (int i=0;i<16;i++) printf("%02x", ref[i]); printf("\n");
    printf("ref tag: "); for (int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");

    /* build our key struct: [Htable 16*16=256][AES_KEY ...] */
    unsigned char ks[512]; memset(ks, 0, sizeof(ks));
    aesni_set_encrypt_key(keyb, 128, ks + 256);  /* put key at +256? kernel uses rcx-128 for Htable and rcx+128 for key.
       Let's re-read: r14 = rcx - 128 (Htable base area), rcx = rcx + 128 (key).
       So the pointer we pass must be such that key is at ptr+128 and Htable at ptr-128.
       Htable is 16 u128 = 256 bytes, located at ptr-128 .. ptr+128. Key starts at ptr+128.
       So layout: base = ptr-128; Htable at base[0..255]; key at base[256]. */
    unsigned char *block = aligned_alloc(64, 256 + 256);
    memset(block, 0, 512);
    aesni_set_encrypt_key(keyb, 128, block + 256);
    unsigned char H[16]; memset(H, 0, 16);
    aesni_encrypt(H, H, block + 256);
    bswap16(H);
    gcm_init_avx((u128*)block, (u128*)H);

    unsigned char *keyptr = block + 128; /* so keyptr-128 = block, keyptr+128 = block+256 */

    /* ivec: nonce || counter(1) big-endian, and the function reads counter from offset 12 */
    unsigned char ivec[16];
    memcpy(ivec, nonce, 12);
    ivec[12]=0; ivec[13]=0; ivec[14]=0; ivec[15]=1;
