#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <openssl/evp.h>

typedef struct { uint64_t hi, lo; } u128;
void gcm_init_avx(u128 Htable[16], const u128 *H);
void gcm_ghash_avx(u128 *Xi, const u128 Htable[16], const unsigned char *inp, size_t len);
int aesni_set_encrypt_key(const unsigned char *userKey, int bits, void *key);
void aesni_encrypt(const unsigned char *in, unsigned char *out, const void *key);
size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
    const void *key, unsigned char ivec[16], u128 *Xi, const void *Htable);

static void bswap16(unsigned char *p) {
    for (int i = 0; i < 8; i++) { unsigned char t=p[i]; p[i]=p[15-i]; p[15-i]=t; }
}
static void xor16(unsigned char *d, const unsigned char *a, const unsigned char *b) {
    for (int i = 0; i < 16; i++) d[i] = a[i] ^ b[i];
}
static double now() { struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec + ts.tv_nsec*1e-9; }

/* Full AES-GCM encrypt using the stitched kernel + ghash for tail/tag. */
static void gcm_encrypt(const unsigned char *key, int keybits,
                        const unsigned char *nonce, size_t nlen,
                        const unsigned char *pt, size_t plen,
                        const unsigned char *aad, size_t alen,
                        unsigned char *ct, unsigned char tag[16]) {
    unsigned char aeskey[256]; memset(aeskey, 0, sizeof(aeskey));
    aesni_set_encrypt_key(key, keybits, aeskey);
    unsigned char H[16]; memset(H, 0, 16);
    aesni_encrypt(H, H, aeskey);
    unsigned char H_bs[16]; memcpy(H_bs, H, 16); bswap16(H_bs);
    u128 Htable[16];
    gcm_init_avx(Htable, (u128*)H_bs);

    /* J0 for 12-byte nonce: nonce || 0x00000001 */
    unsigned char J0[16]; memset(J0, 0, 16);
    memcpy(J0, nonce, 12); J0[15] = 1;

    /* initial counter for kernel = J0 with counter incremented to 2 */
    unsigned char ivec[16]; memcpy(ivec, J0, 16); ivec[15] = 2;

    size_t bulk = plen & ~(size_t)0xf; /* kernel handles multiples of 16, but processes in 96-byte chunks and returns multiple of 96? */
    /* The kernel returned 4032 for 4096, i.e. it leaves a tail. It requires len >= 0x120 and returns len rounded down to multiple of 96? 
       4032 = 4096 - 64. Let's just call it and use the return value. */
    u128 Xi; memset(&Xi, 0, sizeof(Xi));
    size_t done = 0;
    if (bulk >= 0x120) {
        done = aesni_gcm_encrypt(pt, ct, bulk, aeskey, ivec, &Xi, Htable);
    }
    /* Xi currently holds GHASH state over `done` bytes (byte-swapped per the kernel). 
       For the tail, compute CTR manually and GHASH. */

    /* Encrypt tail with aesni_ctr32 starting at counter = 2 + done/16 */
    size_t tail = plen - done;
    if (tail) {
        unsigned char iv2[16]; memcpy(iv2, J0, 16);
        uint32_t c0 = 2 + (uint32_t)(done / 16);
        iv2[12] = c0 >> 24; iv2[13] = c0 >> 16; iv2[14] = c0 >> 8; iv2[15] = c0;
        /* manual CTR for tail */
        unsigned char stream[16];
        size_t off = 0;
        while (off < tail) {
            aesni_encrypt(iv2, stream, aeskey);
            size_t m = tail - off; if (m > 16) m = 16;
            for (size_t i = 0; i < m; i++) ct[done + off + i] = pt[done + off + i] ^ stream[i];
            /* increment counter */
            for (int k = 15; k >= 12; k--) { if (++iv2[k]) break; }
            off += m;
        }
    }

    /* Now compute GHASH over AAD and ciphertext ourselves to get the tag, 
       rather than trusting Xi, and compare. Use gcm_ghash_avx which expects byte-swapped input? 
       Let's test both conventions below in main. For now compute tag via a second EVP? No, we want speed.
       We'll verify Xi convention in main. */
    (void)aad; (void)alen; (void)tag;
    memcpy(tag, &Xi, 16);
}

int main() {
    unsigned char key[16]; memset(key, 1, 16);
    unsigned char nonce[12]; memset(nonce, 2, 12);
    unsigned char aad[32]; memset(aad, 3, 32);
    size_t n = 4096;
    unsigned char *pt = malloc(n); memset(pt, 0x5a, n);
    unsigned char *ct = malloc(n);
    unsigned char tag[16];

    /* reference */
    EVP_CIPHER_CTX *e = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(e, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(e, NULL, NULL, key, nonce);
    int outl=0;
    EVP_EncryptUpdate(e, NULL, &outl, aad, 32);
    unsigned char *ref = malloc(n);
    EVP_EncryptUpdate(e, ref, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(e, ref, &outl);
    unsigned char reftag[16];
    EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_GET_TAG, 16, reftag);

    gcm_encrypt(key, 128, nonce, 12, pt, n, aad, 32, ct, tag);
    printf("ct match first 4032: %d\n", memcmp(ct, ref, 4032)==0);
    printf("ct match all 4096: %d\n", memcmp(ct, ref, 4096)==0);
    printf("our ct[4032:4048]: "); for (int i=4032;i<4048;i++) printf("%02x", ct[i]); printf("\n");
    printf("ref ct[4032:4048]: "); for (int i=4032;i<4048;i++) printf("%02x", ref[i]); printf("\n");
    printf("Xi(tag buf): "); for (int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");

    /* Compute GHASH over full ciphertext with gcm_ghash_avx and compare to what tag needs */
    unsigned char aeskey[256]; memset(aeskey,0,sizeof(aeskey));
    aesni_set_encrypt_key(key, 128, aeskey);
    unsigned char H[16]; memset(H,0,16); aesni_encrypt(H,H,aeskey);
    unsigned char Hb[16]; memcpy(Hb,H,16); bswap16(Hb);
    u128 Htable[16]; gcm_init_avx(Htable, (u128*)Hb);
    u128 Xi; memset(&Xi,0,sizeof(Xi));
    gcm_ghash_avx(&Xi, Htable, ref, 4096);
    printf("ghash(ct): "); unsigned char *xp=(unsigned char*)&Xi; for (int i=0;i<16;i++) printf("%02x", xp[i]); printf("\n");
    printf("ref tag : "); for (int i=0;i<16;i++) printf("%02x", reftag[i]); printf("\n");

    /* bench */
    n = 60000UL*1024;
    pt = malloc(n); ct = malloc(n); memset(pt, 0x5a, n);
    int reps=4; double t0=now();
    for(int i=0;i<reps;i++) gcm_encrypt(key,128,nonce,12,pt,n,aad,32,ct,tag);
    double t1=now();
    printf("full fn (incl setup): %.2f ms\n", (t1-t0)/reps*1000);
    return 0;
}
