#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <openssl/evp.h>

typedef struct { uint64_t hi, lo; } u128;
void gcm_init_avx(u128 Htable[16], const u128 *H);
void gcm_ghash_avx(u128 *Xi, const u128 Htable[16], const unsigned char *inp, size_t len);
int aesni_set_encrypt_key(const unsigned char*, int, void*);
void aesni_encrypt(const unsigned char*, unsigned char*, const void*);
size_t aesni_gcm_encrypt(const unsigned char*, unsigned char*, size_t, const void*, unsigned char[16], u128*, const void*);

static void bswap16(unsigned char *p){ for(int i=0;i<8;i++){unsigned char t=p[i];p[i]=p[15-i];p[15-i]=t;} }
static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main(){
    unsigned char key[16]; memset(key,1,16);
    unsigned char nonce[12]; memset(nonce,2,12);
    size_t n = 60000UL*1024; /* divisible by 16 and by 96? */
    printf("n %% 96 = %zu, n %% 16 = %zu\n", n%96, n%16);
    unsigned char *pt = malloc(n), *ct = malloc(n);
    memset(pt, 0x5a, n);

    unsigned char aeskey[256]; memset(aeskey,0,sizeof(aeskey));
    aesni_set_encrypt_key(key,128,aeskey);
    unsigned char H[16]; memset(H,0,16); aesni_encrypt(H,H,aeskey);
    bswap16(H);
    u128 Htable[16]; gcm_init_avx(Htable,(u128*)H);

    unsigned char ivec[16]; memcpy(ivec,nonce,12); ivec[12]=0;ivec[13]=0;ivec[14]=0;ivec[15]=2;
    u128 Xi; memset(&Xi,0,sizeof(Xi));
    int reps=4;
    double t0=now();
    size_t done=0;
    for(int i=0;i<reps;i++){
        unsigned char iv2[16]; memcpy(iv2,ivec,16);
        u128 Xi2; memset(&Xi2,0,sizeof(Xi2));
        done = aesni_gcm_encrypt(pt, ct, n, aeskey, iv2, &Xi2, Htable);
        Xi = Xi2;
    }
    double t1=now();
    printf("kernel on %zu bytes, done=%zu: %.2f ms\n", n, done, (t1-t0)/reps*1000);

    /* tail size */
    printf("tail = %zu bytes\n", n-done);

    /* verify ct against EVP on a small slice */
    EVP_CIPHER_CTX *e = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(e, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(e, NULL, NULL, key, nonce);
    int outl=0; unsigned char *ref=malloc(n);
    EVP_EncryptUpdate(e, ref, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(e, ref, &outl);
    printf("ct match over done bytes: %d\n", memcmp(ct, ref, done)==0);

    /* What is Xi? Compare with ghash of first `done` bytes */
    u128 Xi2; memset(&Xi2,0,sizeof(Xi2));
    gcm_ghash_avx(&Xi2, Htable, ref, done);
    printf("kernel Xi: "); unsigned char *a=(unsigned char*)&Xi; for(int i=0;i<16;i++) printf("%02x",a[i]); printf("\n");
    printf("ghash  Xi: "); unsigned char *b=(unsigned char*)&Xi2; for(int i=0;i<16;i++) printf("%02x",b[i]); printf("\n");
    /* byte-swapped compare */
    unsigned char xb[16]; memcpy(xb,&Xi,16); bswap16(xb);
    printf("kernel Xi bswap: "); for(int i=0;i<16;i++) printf("%02x",xb[i]); printf("\n");
    return 0;
}
