int aesni_set_encrypt_key(const unsigned char*, int, void*);
void aesni_encrypt(const unsigned char*, unsigned char*, const void*);
size_t aesni_gcm_encrypt(const unsigned char*, unsigned char*, size_t, const void*, unsigned char[16], u128*, const void*);

static void bswap16(unsigned char *p){ for(int i=0;i<8;i++){unsigned char t=p[i];p[i]=p[15-i];p[15-i]=t;} }
static void xor16(unsigned char *d, const unsigned char *a, const unsigned char *b){ for(int i=0;i<16;i++) d[i]=a[i]^b[i]; }

/* gcm_gmult_avx? check symbol */
void gcm_gmult_avx(u128 *Xi, const u128 Htable[16]);

static void p16(const char *l, const unsigned char *p){ printf("%s ", l); for(int i=0;i<16;i++) printf("%02x", p[i]); printf("\n"); }

int main(){
    unsigned char key[16]; memset(key,1,16);
    unsigned char nonce[12]; memset(nonce,2,12);
    unsigned char aad[32]; memset(aad,3,32);
    size_t n = 61440; /* multiple of 96 */
    unsigned char *pt = malloc(n); memset(pt, 0x5a, n);

    /* reference */
    EVP_CIPHER_CTX *e = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(e, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(e, NULL, NULL, key, nonce);
    int outl=0;
    EVP_EncryptUpdate(e, NULL, &outl, aad, 32);
    unsigned char *ct = malloc(n);
    EVP_EncryptUpdate(e, ct, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(e, ct, &outl);
    unsigned char reftag[16];
    EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_GET_TAG, 16, reftag);
    p16("ref tag", reftag);

    unsigned char aeskey[256]; memset(aeskey,0,sizeof(aeskey));
    aesni_set_encrypt_key(key,128,aeskey);
    unsigned char H[16]; memset(H,0,16); aesni_encrypt(H,H,aeskey);
    unsigned char EK0[16];
    unsigned char J0[16]; memset(J0,0,16); memcpy(J0,nonce,12); J0[15]=1;
    aesni_encrypt(J0, EK0, aeskey);
    p16("E(K,J0)", EK0);

    unsigned char Hb[16]; memcpy(Hb,H,16); bswap16(Hb);
    u128 Htable[16]; gcm_init_avx(Htable,(u128*)Hb);

    /* Build GHASH input: AAD padded to 16, ct padded to 16, then len block */
    size_t alen = 32;
    size_t aad_blocks = (alen+15)/16;
    size_t ct_blocks = (n+15)/16;
    size_t buflen = (aad_blocks + ct_blocks + 1) * 16;
    unsigned char *buf = calloc(1, buflen);
    memcpy(buf, aad, alen);
    memcpy(buf + aad_blocks*16, ct, n);
    uint64_t alen_bits = alen * 8, clen_bits = n * 8;
    unsigned char *lenb = buf + (aad_blocks+ct_blocks)*16;
    for (int i=0;i<8;i++){ lenb[7-i] = alen_bits >> (8*i); lenb[15-i] = clen_bits >> (8*i); }

    u128 Xi; memset(&Xi,0,sizeof(Xi));
    gcm_ghash_avx(&Xi, Htable, buf, buflen);
    unsigned char S[16]; memcpy(S, &Xi, 16);
    p16("ghash full (raw)", S);
    unsigned char Sb[16]; memcpy(Sb,S,16); bswap16(Sb);
    p16("ghash full bswap", Sb);
    unsigned char tag[16]; xor16(tag, S, EK0); p16("tag = S xor EK0", tag);
    xor16(tag, Sb, EK0); p16("tag = Sb xor EK0", tag);

    /* Try: GHASH of ct only, then fold AAD and lengths via gcm_gmult? */
    memset(&Xi,0,sizeof(Xi));
    gcm_ghash_avx(&Xi, Htable, ct, n);
    p16("ghash(ct)", (unsigned char*)&Xi);

    /* Standard approach but byte-swap each block before ghash */
    for (size_t i=0;i<buflen;i+=16) bswap16(buf+i);
    memset(&Xi,0,sizeof(Xi));
    gcm_ghash_avx(&Xi, Htable, buf, buflen);
    memcpy(S,&Xi,16);
    p16("ghash preswapped raw", S);
    xor16(tag, S, EK0); p16("tag preswap xor EK0", tag);
    bswap16(S); xor16(tag, S, EK0); p16("tag preswap bswap xor EK0", tag);
    return 0;
}
