void gcm_gmult_avx(u128 *Xi, const u128 Htable[16]);
int aesni_set_encrypt_key(const unsigned char*, int, void*);
void aesni_encrypt(const unsigned char*, unsigned char*, const void*);

static void bswap16(unsigned char *p){ for(int i=0;i<8;i++){unsigned char t=p[i];p[i]=p[15-i];p[15-i]=t;} }
static int eq16(const unsigned char *a, const unsigned char *b){ return memcmp(a,b,16)==0; }
static void p16(const char *l, const unsigned char *p){ printf("%-28s ", l); for(int i=0;i<16;i++) printf("%02x", p[i]); printf("\n"); }

/* bit reflection of a byte */
static unsigned char rev8(unsigned char b){ b=(b&0xF0)>>4|(b&0x0F)<<4; b=(b&0xCC)>>2|(b&0x33)<<2; b=(b&0xAA)>>1|(b&0x55)<<1; return b; }
static void reflect16(unsigned char *p){ unsigned char t[16]; for(int i=0;i<16;i++) t[i]=rev8(p[15-i]); memcpy(p,t,16); }

int main(){
    unsigned char key[16]; memset(key,1,16);
