    EVP_CIPHER_CTX *e = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(e, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(e, NULL, NULL, key, nonce);
    int outl=0; EVP_EncryptUpdate(e, NULL, &outl, aad, 32);
    unsigned char *ct = malloc(n);
    EVP_EncryptUpdate(e, ct, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(e, ct, &outl);
    unsigned char reftag[16]; EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_GET_TAG, 16, reftag);
    p16("ref tag", reftag);

    unsigned char aeskey[256]; memset(aeskey,0,sizeof(aeskey));
    aesni_set_encrypt_key(key,128,aeskey);
    unsigned char H[16]; memset(H,0,16); aesni_encrypt(H,H,aeskey);
    p16("H", H);
    unsigned char EK0[16];
    unsigned char J0[16]; memset(J0,0,16); memcpy(J0,nonce,12); J0[15]=1;
    aesni_encrypt(J0, EK0, aeskey);

    /* build ghash input (AAD || CT || lengths), all 16-aligned */
    size_t aad_blocks=2, ct_blocks=n/16;
    size_t buflen=(aad_blocks+ct_blocks+1)*16;
    unsigned char *buf=calloc(1,buflen);
    memcpy(buf,aad,32); memcpy(buf+32,ct,n);
    unsigned char *lenb=buf+(aad_blocks+ct_blocks)*16;
    uint64_t ab=32*8, cb=n*8;
    for(int i=0;i<8;i++){ lenb[7-i]=ab>>(8*i); lenb[15-i]=cb>>(8*i); }

    /* Try several H transformations and both init functions */
    void (*inits[])(u128*, const u128*) = {gcm_init_avx, gcm_init_clmul};
    const char *inames[] = {"avx", "clmul"};
    void (*ghash[])(u128*, const u128*, const unsigned char*, size_t) = {gcm_ghash_avx, gcm_ghash_clmul};

    unsigned char variants[4][16];
    memcpy(variants[0], H, 16);                      /* raw */
    memcpy(variants[1], H, 16); bswap16(variants[1]); /* bswap */
    memcpy(variants[2], H, 16); reflect16(variants[2]); /* reflected */
    memcpy(variants[3], H, 16); bswap16(variants[3]); reflect16(variants[3]);
    const char *vnames[] = {"raw", "bswap", "reflect", "bswap+reflect"};

    for (int vi=0; vi<4; vi++) {
        for (int ii=0; ii<2; ii++) {
            u128 Htable[16];
