            u128 Xi; memset(&Xi,0,sizeof(Xi));
            ghash[ii](&Xi, Htable, buf, buflen);
            unsigned char S[16]; memcpy(S,&Xi,16);
            unsigned char tag[16];
            for (int i=0;i<16;i++) tag[i]=S[i]^EK0[i];
            int m1 = eq16(tag, reftag);
            unsigned char Sb[16]; memcpy(Sb,S,16); bswap16(Sb);
            unsigned char tag2[16]; for(int i=0;i<16;i++) tag2[i]=Sb[i]^EK0[i];
            int m2 = eq16(tag2, reftag);
            if (m1 || m2) printf("MATCH vi=%s init=%s m1=%d m2=%d\n", vnames[vi], inames[ii], m1, m2);
        }
    }
    printf("done scanning\n");

    /* Also test: maybe EK0 needs bswap before xor */
    u128 Htable[16];
    unsigned char Hb[16]; memcpy(Hb,H,16); bswap16(Hb);
    gcm_init_avx(Htable,(u128*)Hb);
    u128 Xi; memset(&Xi,0,sizeof(Xi));
    gcm_ghash_avx(&Xi,Htable,buf,buflen);
    unsigned char S[16]; memcpy(S,&Xi,16);
    unsigned char EK0b[16]; memcpy(EK0b,EK0,16); bswap16(EK0b);
    unsigned char tag[16];
    for(int i=0;i<16;i++) tag[i]=S[i]^EK0b[i];
    p16("S xor EK0b", tag);
    unsigned char Sb[16]; memcpy(Sb,S,16); bswap16(Sb);
    for(int i=0;i<16;i++) tag[i]=Sb[i]^EK0b[i];
    p16("Sb xor EK0b", tag);
    return 0;
}
