{"command":"cd "$HOME/gcmbuild" && cat > mygcm.c << 'EOF'
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <openssl/evp.h>

/* AES-NI key schedule + block encrypt via the OpenSSL symbols (already validated). */
int aesni_set_encrypt_key(const unsigned char*, int, void*);
void aesni_encrypt(const unsigned char*, unsigned char*, const void*);
void aesni_ctr32_encrypt_blocks(const unsigned char*, unsigned char*, size_t, const void*, const unsigned char[16]);

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

/* Reflected GHASH: multiply in GF(2^128) with reduction polynomial x^128 + x^7 + x^2 + x + 1,
   operating on bit-reflected (little-endian) representations so PCLMUL applies directly. */
static inline __m128i ghash_reduce(__m128i lo, __m128i hi){
    /* Standard Intel reduction (Gueron). lo = bits [127:0], hi = bits [255:128] of the product,
       both in reflected representation. */
    __m128i tmp0, tmp1, tmp2;
    tmp0 = lo;
    tmp1 = _mm_clmulepi64_si128(lo, _mm_set_epi32(0,0,0,0x87), 0x11); /* hi64(lo) * 0x87 -> low */
    /* Use the well-known 2-step reduction with polynomial 0x87 reflected. */
    const __m128i poly = _mm_set_epi32(0, 0, 0, 0x87);
    /* reduction of the high half into the low half */
    __m128i t = _mm_clmulepi64_si128(hi, poly, 0x00); /* lo64(hi) * poly */
    lo = _mm_xor_si128(lo, _mm_slli_si128(t, 8));
    lo = _mm_xor_si128(lo, _mm_srli_si128(t, 8));
    t = _mm_clmulepi64_si128(hi, poly, 0x01); /* hi64(hi) * poly */
    lo = _mm_xor_si128(lo, t);
    (void)tmp0; (void)tmp1; (void)tmp2;
    return lo;
}

/* Simpler, validated approach: implement reduction exactly as the reference algorithm in C,
   but only for the short tag computation. The bulk data dominates, so even a moderately fast
   GHASH is fine. Let's first get correctness with a straightforward 128-bit reflected multiply
   and then optimize. */

static uint64_t rev64(uint64_t x){
    x = ((x & 0x5555555555555555ULL) << 1) | ((x >> 1) & 0x5555555555555555ULL);
    x = ((x & 0x3333333333333333ULL) << 2) | ((x >> 2) & 0x3333333333333333ULL);
    x = ((x & 0x0f0f0f0f0f0f0f0fULL) << 4) | ((x >> 4) & 0x0f0f0f0f0f0f0f0fULL);
    x = ((x & 0x00ff00ff00ff00ffULL) << 8) | ((x >> 8) & 0x00ff00ff00ff00ffULL);
    x = ((x & 0x0000ffff0000ffffULL) << 16) | ((x >> 16) & 0x0000ffff0000ffffULL);
    x = (x << 32) | (x >> 32);
    return x;
}

/* GF multiply, standard (non-reflected) representation, using PCLMUL + shift reduction. */
static void gf_mul(const unsigned char a[16], const unsigned char b[16], unsigned char out[16]){
    uint64_t a0 = 0, a1 = 0, b0 = 0, b1 = 0;
    for (int i = 0; i < 8; i++){ a1 = (a1<<8) | a[i]; a0 = (a0<<8) | a[8+i]; }
    for (int i = 0; i < 8; i++){ b1 = (b1<<8) | b[i]; b0 = (b0<<8) | b[8+i]; }
    /* reflect bits so PCLMUL (which is little-endian) matches big-endian polynomial */
    __m128i xa = _mm_set_epi64x(rev64(a1), rev64(a0));
    __m128i xb = _mm_set_epi64x(rev64(b1), rev64(b0));
    __m128i z0 = _mm_clmulepi64_si128(xa, xb, 0x00);
    __m128i z2 = _mm_clmulepi64_si128(xa, xb, 0x11);
    __m128i z1 = _mm_xor_si128(_mm_clmulepi64_si128(xa, xb, 0x01), _mm_clmulepi64_si128(xa, xb, 0x10));
    /* Karatsuba combine: product = z2*x^128 + (z1^z0^z2)*x^64 + z0, but we already have z1 as cross terms.
       reflected reduction polynomial: 0xe1 at the high end == 0x87 reflected. */
    __m128i t = _mm_srli_si128(z1, 8);
    z2 = _mm_xor_si128(z2, t);
    t = _mm_slli_si128(z1, 8);
    z0 = _mm_xor_si128(z0, t);
    /* reduce z2 into z0, reflected poly 0x87 */
    __m128i poly = _mm_set_epi64x(0, 0x87);
    __m128i r = _mm_clmulepi64_si128(z2, poly, 0x00);
    z0 = _mm_xor_si128(z0, _mm_slli_si128(r, 8));
    __m128i r2 = _mm_clmulepi64_si128(z2, poly, 0x01);
    z0 = _mm_xor_si128(z0, r2);
    z0 = _mm_xor_si128(z0, _mm_srli_si128(_mm_clmulepi64_si128(z2, poly, 0x00), 8));
    unsigned long long lo = _mm_extract_epi64(z0, 0);
    unsigned long long hi = _mm_extract_epi64(z0, 1);
    uint64_t R0 = rev64(lo), R1 = rev64(hi);
    for (int i = 7; i >= 0; i--){ out[7-i] = R1 >> (8*i); out[15-i] = R0 >> (8*i); }
}

int main(){
    unsigned char key[16]; memset(key,1,16);
    unsigned char nonce[12]; memset(nonce,2,12);
    unsigned char aad[32]; memset(aad,3,32);
    size_t n = 61440;
    unsigned char *pt = malloc(n); memset(pt,0x5a,n);

    EVP_CIPHER_CTX *e = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(e, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(e, NULL, NULL, key, nonce);
    int outl=0; EVP_EncryptUpdate(e, NULL, &outl, aad, 32);
    unsigned char *ct = malloc(n);
    EVP_EncryptUpdate(e, ct, &outl, pt, (int)n);
    EVP_EncryptFinal_ex(e, ct, &outl);
    unsigned char reftag[16]; EVP_CIPHER_CTX_ctrl(e, EVP_CTRL_GCM_GET_TAG, 16, reftag);

    unsigned char aeskey[256]; memset(aeskey,0,sizeof(aeskey));
    aesni_set_encrypt_key(key,128,aeskey);
    unsigned char H[16]; memset(H,0,16); aesni_encrypt(H,H,aeskey);
    unsigned char J0[16]; memset(J0,0,16); memcpy(J0,nonce,12); J0[15]=1;
    unsigned char EK0[16]; aesni_encrypt(J0, EK0, aeskey);

    /* GHASH */
    unsigned char Y[16]; memset(Y,0,16);
    unsigned char blk[16], tmp[16];
    for (size_t i=0;i<32;i+=16){
        for(int k=0;k<16;k++) blk[k]=Y[k]^aad[i+k];
        gf_mul(blk, H, Y);
    }
    for (size_t i=0;i<n;i+=16){
        for(int k=0;k<16;k++) blk[k]=Y[k]^ct[i+k];
        gf_mul(blk, H, Y);
    }
    unsigned char lenb[16]; memset(lenb,0,16);
    uint64_t ab=32*8, cb=n*8;
    for(int i=0;i<8;i++){ lenb[7-i]=ab>>(8*i); lenb[15-i]=cb>>(8*i); }
    for(int k=0;k<16;k++) blk[k]=Y[k]^lenb[k];
    gf_mul(blk, H, Y);
    unsigned char tag[16];
    for(int k=0;k<16;k++) tag[k]=Y[k]^EK0[k];
    printf("ref tag "); for(int k=0;k<16;k++) printf("%02x", reftag[k]); printf("\n");
    printf("our tag "); for(int k=0;k<16;k++) printf("%02x", tag[k]); printf("\n");
    printf("match %d\n", memcmp(tag, reftag, 16)==0);
    return 0;
}
EOF
