#include <wmmintrin.h>
#include <emmintrin.h>
#include <tmmintrin.h>
#include <smmintrin.h>

/* Trusted reference: bit-by-bit GHASH multiply (big-endian), slow but correct. */
static void gf_ref(const unsigned char a[16], const unsigned char b[16], unsigned char out[16]){
    unsigned char z[16]={0}, v[16]; memcpy(v,b,16);
    for(int i=0;i<128;i++){
        int bit = (a[i>>3] >> (7-(i&7))) & 1;
        if(bit) for(int k=0;k<16;k++) z[k]^=v[k];
        int lsb = v[15] & 1;
        for(int k=15;k>0;k--) v[k]=(v[k]>>1)|((v[k-1]&1)<<7);
        v[0]>>=1;
        if(lsb) v[0]^=0xe1;
    }
    memcpy(out,z,16);
}

static void p16(const char *l, const unsigned char *p){ printf("%s ",l); for(int i=0;i<16;i++) printf("%02x",p[i]); printf("\n"); }

int main(){
    unsigned char a[16], b[16], out[16];
    memset(a,0x5a,16); memset(b,0,16); b[0]=0xb6;
    gf_ref(a,b,out);
    p16("ref", out);
    return 0;
}
