static unsigned char rev8(unsigned char b){ b=(b&0xF0)>>4|(b&0x0F)<<4; b=(b&0xCC)>>2|(b&0x33)<<2; b=(b&0xAA)>>1|(b&0x55)<<1; return b; }

/* trusted */
static void gf_ref(const unsigned char a[16], const unsigned char b[16], unsigned char out[16]){
    unsigned char z[16]={0}, v[16]; memcpy(v,b,16);
    for(int i=0;i<128;i++){
        if((a[i>>3]>>(7-(i&7)))&1) for(int k=0;k<16;k++) z[k]^=v[k];
        int lsb=v[15]&1;
        for(int k=15;k>0;k--) v[k]=(v[k]>>1)|((v[k-1]&1)<<7);
        v[0]>>=1; if(lsb) v[0]^=0xe1;
    }
    memcpy(out,z,16);
}

int main(){
    unsigned char H[16]; memset(H,0,16); H[0]=0xb6; H[1]=0xae;
    unsigned char blk[16]; memset(blk,0x5a,16);
    unsigned char trusted[16]; gf_ref(blk, H, trusted);
    printf("trusted "); for(int i=0;i<16;i++) printf("%02x",trusted[i]); printf("\n");

    /* Try gcm_ghash_avx with H passed raw and bswapped, compare output under transforms to trusted. */
    unsigned char Hv[2][16]; memcpy(Hv[0],H,16); memcpy(Hv[1],H,16); bswap16(Hv[1]);
    const char *hn[]={"raw","bswap"};
    for(int vi=0; vi<2; vi++){
        u128 T[16]; gcm_init_avx(T,(u128*)Hv[vi]);
        u128 Xi; memset(&Xi,0,sizeof(Xi));
        gcm_ghash_avx(&Xi,T,blk,16);
        unsigned char S[16]; memcpy(S,&Xi,16);
        unsigned char cands[4][16];
        memcpy(cands[0],S,16);
        memcpy(cands[1],S,16); bswap16(cands[1]);
        memcpy(cands[2],S,16); for(int k=0;k<16;k++) cands[2][k]=rev8(cands[2][k]);
        memcpy(cands[3],S,16); bswap16(cands[3]); for(int k=0;k<16;k++) cands[3][k]=rev8(cands[3][k]);
        const char *cn[]={"id","bswap","revb","bswap+revb"};
        for(int ci=0; ci<4; ci++){
            int m = memcmp(cands[ci], trusted, 16)==0;
            if(m) printf("MATCH H=%s out=%s\n", hn[vi], cn[ci]);
        }
        printf("H=%s asm_out ", hn[vi]); for(int i=0;i<16;i++) printf("%02x",S[i]); printf("\n");
    }
    return 0;
}
